uv = vec2((uv.x)*q3 - (uv.y) * q2,(uv.x)* q2 + (uv.y) * q3)*1.25;
uv = 1.0 - abs( fract( uv * 0.5 ) * 2.0 - 1.0 ); // Eo.S' mirror code
