vec2 c = vec2(.4,.5*q1);
vec2 my_uv2 = (uv_orig-0.5)*zoom;
my_uv2 = vec2(my_uv2.x*my_uv2.x - my_uv2.y*my_uv2.y, 2.0 * my_uv2.x*my_uv2.y) + c;
uv = my_uv2;
// 24 bit gray value:
float gray = GetPixel(uv).x + 256.0*GetPixel(uv).y + 256.0*256*GetPixel(uv).z;
// in fact, this palette doesn't need such a high-precision gray value, but try putting a fractal palette on it ;)
